css:
.rm-t-sidebar-ink{display:grid;grid-template-columns:250px minmax(0,1fr);align-items:stretch;min-height:1123px;padding:0;background:linear-gradient(90deg,#101d1a 0 250px,#ffffff 250px 100%);color:#2b3a36;font-size:13px;line-height:1.66;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Noto Sans SC",sans-serif;}
.rm-t-sidebar-ink .rm-head{grid-column:1;grid-row:1;display:block;margin:0;padding:46px 26px 40px;background:transparent;border:0;color:#edf4f1;}
.rm-t-sidebar-ink .rm-head.rm-has-photo{display:block;grid-template-columns:none;gap:0;}
.rm-t-sidebar-ink .rm-head-main{min-width:0;}
.rm-t-sidebar-ink .rm-photo{width:110px;height:110px;margin:0 0 20px;background:rgba(255,255,255,.08);border:2px solid rgba(255,255,255,.26);}
.rm-t-sidebar-ink .rm-photo.rm-photo-contain-box{background:rgba(255,255,255,.10);}
.rm-t-sidebar-ink .rm-name{margin:0;font-size:29px;line-height:1.22;font-weight:600;letter-spacing:.06em;color:#f6faf8;}
.rm-t-sidebar-ink .rm-name::after{content:"";display:block;width:36px;height:3px;margin:14px 0 0;background:#c2a06a;}
.rm-t-sidebar-ink .rm-role{margin:11px 0 0;font-size:11px;line-height:1.62;letter-spacing:.14em;color:#a9c8bd;}
.rm-t-sidebar-ink .rm-contact{grid-template-columns:minmax(0,1fr);gap:11px;margin:26px 0 0;}
.rm-t-sidebar-ink .rm-head.rm-has-photo .rm-contact{grid-template-columns:minmax(0,1fr);width:auto;margin-top:26px;}
.rm-t-sidebar-ink .rm-c{flex-direction:column;align-items:flex-start;gap:1px;min-width:0;}
.rm-t-sidebar-ink .rm-k{font-size:9px;letter-spacing:.22em;color:#7f9d92;text-transform:uppercase;}
.rm-t-sidebar-ink .rm-v{font-size:11.5px;line-height:1.5;color:#e4efeb;overflow-wrap:anywhere;}
.rm-t-sidebar-ink .rm-body{grid-column:2;grid-row:1;padding:42px 42px 46px;}
.rm-t-sidebar-ink .rm-body > .rm-sec{margin-top:24px;}
.rm-t-sidebar-ink .rm-body > .rm-sec:first-child{margin-top:0;}
.rm-t-sidebar-ink .rm-sec-h{display:flex;align-items:center;gap:10px;margin:0 0 11px;}
.rm-t-sidebar-ink .rm-sec-t{font-size:13.5px;font-weight:700;letter-spacing:.14em;color:#16302b;}
.rm-t-sidebar-ink .rm-sec-t::before{content:"";display:inline-block;width:5px;height:5px;margin-right:9px;vertical-align:2px;background:#c2a06a;}
.rm-t-sidebar-ink .rm-sec-h::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,rgba(194,160,106,.55),rgba(194,160,106,0));}
.rm-t-sidebar-ink .rm-sec-hobbies .rm-tags{gap:6px;}
.rm-t-sidebar-ink .rm-sec-campus .rm-item-t{color:#16302b;}
.rm-t-sidebar-ink .rm-summary{margin:0;font-size:12.6px;line-height:1.76;color:#48564f;}
.rm-t-sidebar-ink .rm-item{margin:0 0 12px;}
.rm-t-sidebar-ink .rm-item-t{font-weight:650;color:#16302b;}
.rm-t-sidebar-ink .rm-item-role{margin-left:8px;font-size:12.2px;color:#6d7c76;}
.rm-t-sidebar-ink .rm-date{font-size:11px;color:#8d9a95;font-variant-numeric:tabular-nums;}
.rm-t-sidebar-ink .rm-item-sub{margin-top:2px;font-size:11.5px;color:#78867f;}
.rm-t-sidebar-ink .rm-bullets{margin:5px 0 0;padding-left:15px;}
.rm-t-sidebar-ink .rm-bullets li{margin:3px 0;color:#3f4d47;}
.rm-t-sidebar-ink .rm-bullets li::marker{color:#c2a06a;}
.rm-t-sidebar-ink .rm-edu-courses{margin-top:3px;font-size:11.5px;color:#6d7c76;}
.rm-t-sidebar-ink .rm-edu-courses .rm-k{margin-right:7px;color:#93a49d;}
.rm-t-sidebar-ink .rm-award-row{margin:0 0 7px;align-items:baseline;}
.rm-t-sidebar-ink .rm-award-t{font-weight:600;color:#16302b;}
.rm-t-sidebar-ink .rm-award-desc{font-size:11.5px;color:#6d7c76;}
.rm-t-sidebar-ink .rm-skill-row{grid-template-columns:118px minmax(0,1fr);gap:10px;margin:0 0 7px;}
.rm-t-sidebar-ink .rm-skill-k{font-size:12px;font-weight:600;letter-spacing:.02em;color:#16302b;}
.rm-t-sidebar-ink .rm-tag{display:inline-block;padding:1px 9px;border:1px solid #16302b;border-radius:3px;background:#16302b;color:#eaf2ee;font-size:11px;line-height:1.7;}
.rm-t-sidebar-ink .rm-tags{gap:5px;}
.rm-t-sidebar-ink strong{color:#0f2620;}
